document.getElementById('lead-form').addEventListener('submit',function(e){e.preventDefault();if(!this.reportValidity())return;const d=new FormData(this);const body=`Bonjour Kévin,\n\nJe souhaite échanger sur mon logement.\n\nNom : ${d.get('nom')}\nE-mail : ${d.get('email')}\nCommune : ${d.get('ville')}\nSituation : ${d.get('situation')}\n\n${d.get('message')}\n\nÀ bientôt.`;window.location.href='mailto:kevin.dolie@solayia.fr?subject='+encodeURIComponent('Mon logement — Solaya Collection')+'&body='+encodeURIComponent(body);document.getElementById('form-status').textContent='Demande préparée. Si aucune messagerie ne s’ouvre, écrivez à kevin.dolie@solayia.fr. Aucun message n’a été envoyé automatiquement.';});
